import fs from "node:fs";
import path from "node:path";

/**
 * Parse a shell-compatible `.env` string, including single-quoted values with `'\''` escapes
 * generated by `wizard/template.sh`.
 */
export function parseDotEnv(content) {
  const result = {};
  const lines = String(content).split(/\r?\n/);

  for (const rawLine of lines) {
    const trimmed = rawLine.trim();
    if (!trimmed || trimmed.startsWith("#")) {
      continue;
    }

    const line = trimmed.startsWith("export ") ? trimmed.slice(7).trimStart() : trimmed;
    const eqIndex = line.indexOf("=");
    if (eqIndex <= 0) {
      continue;
    }

    const key = line.slice(0, eqIndex).trim();
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(key)) {
      continue;
    }

    const rhs = line.slice(eqIndex + 1).trim();
    result[key] = parseEnvValue(rhs);
  }

  return result;
}

function parseEnvValue(rhs) {
  if (!rhs) {
    return "";
  }

  if (rhs.startsWith("'")) {
    let out = "";
    let i = 0;
    while (i < rhs.length) {
      if (rhs[i] === "'") {
        i += 1;
        while (i < rhs.length && rhs[i] !== "'") {
          out += rhs[i];
          i += 1;
        }
        if (i < rhs.length && rhs[i] === "'") {
          i += 1;
        }
        // Handle bash single-quote escape sequence '\''
        if (rhs.startsWith("\\'", i)) {
          out += "'";
          i += 2;
        }
      } else if (rhs[i] === "#") {
        break;
      } else if (/\s/.test(rhs[i])) {
        i += 1;
      } else {
        // Unquoted segment following a quote
        while (i < rhs.length && rhs[i] !== "'" && !/\s/.test(rhs[i])) {
          out += rhs[i];
          i += 1;
        }
      }
    }
    return out;
  }

  if (rhs.startsWith('"')) {
    let out = "";
    let i = 1;
    while (i < rhs.length) {
      const ch = rhs[i];
      if (ch === "\\") {
        const next = rhs[i + 1];
        if (next === "n") out += "\n";
        else if (next === "r") out += "\r";
        else if (next === "t") out += "\t";
        else if (next !== undefined) out += next;
        i += 2;
      } else if (ch === '"') {
        break;
      } else {
        out += ch;
        i += 1;
      }
    }
    return out;
  }

  // Unquoted value: strip inline comment preceded by whitespace
  const commentMatch = rhs.match(/\s+#/);
  return (commentMatch ? rhs.slice(0, commentMatch.index) : rhs).trim();
}

/**
 * Load `.env` from disk into target env map without overwriting existing variables.
 */
export function loadDotEnv(envPath, targetEnv = process.env) {
  if (!fs.existsSync(envPath)) {
    return {};
  }
  const parsed = parseDotEnv(fs.readFileSync(envPath, "utf8"));
  for (const [key, value] of Object.entries(parsed)) {
    if (targetEnv[key] === undefined) {
      targetEnv[key] = value;
    }
  }
  return parsed;
}

/**
 * Load and normalize `config/projects.json` (falling back to `projects.example.json` if absent).
 */
export function loadProjectsConfig(projectsFile, fallbackFile = null) {
  const target = fs.existsSync(projectsFile)
    ? projectsFile
    : fallbackFile && fs.existsSync(fallbackFile)
      ? fallbackFile
      : null;

  if (!target) {
    return {
      defaultRemoteProject: "",
      defaultMode: "accept-edits",
      projects: [],
    };
  }

  const parsed = JSON.parse(fs.readFileSync(target, "utf8"));
  const projects = Array.isArray(parsed.projects) ? parsed.projects : [];
  return {
    defaultRemoteProject: String(parsed.defaultRemoteProject || ""),
    defaultMode: String(parsed.defaultMode || "accept-edits"),
    projects: projects.map((p) => ({
      key: String(p.key || ""),
      name: String(p.name || p.key || ""),
      description: String(p.description || ""),
      remoteProject: String(p.remoteProject || parsed.defaultRemoteProject || ""),
      mode: p.mode ? String(p.mode) : undefined,
      githubRepo: String(p.githubRepo || "").trim(),
      workflowPath: String(p.workflowPath || "WORKFLOW.md").trim() || "WORKFLOW.md",
      localPath: String(p.localPath || "").trim(),
      extraInstructions: String(p.extraInstructions || ""),
      linear: {
        projectIds: normalizeList(p.linear?.projectIds),
        projectSlugs: normalizeList(p.linear?.projectSlugs),
        projectNames: normalizeList(p.linear?.projectNames),
        teamKeys: normalizeList(p.linear?.teamKeys),
        labels: normalizeList(p.linear?.labels),
      },
    })),
  };
}

function normalizeList(value) {
  return Array.isArray(value) ? value.map((item) => String(item).trim()).filter(Boolean) : [];
}

/**
 * Load runtime configuration for agy-linear-bridge.
 */
export function loadConfig(
  rootDir = path.resolve(import.meta.dirname, ".."),
  env = process.env
) {
  const envFile = path.join(rootDir, ".env");
  loadDotEnv(envFile, env);

  const projectsFile = path.join(rootDir, "config", "projects.json");
  const projectsExampleFile = path.join(rootDir, "config", "projects.example.json");
  const projectsConfig = loadProjectsConfig(projectsFile, projectsExampleFile);

  const publicBaseUrl = String(env.PUBLIC_BASE_URL || "")
    .trim()
    .replace(/\/+$/, "")
    .replace(/\/(?:oauth\/callback|webhooks\/linear)$/i, "");

  const port = Number(env.PORT || 8787);
  const webhookMaxAgeMs = Number(env.WEBHOOK_MAX_AGE_MS || 300000);
  const routerTimeoutMs = Number(env.ROUTER_TIMEOUT_MS || 90000);
  const maxConcurrentLaunches = Math.max(1, Number(env.MAX_CONCURRENT_LAUNCHES || 2));

  return {
    rootDir,
    port: Number.isFinite(port) && port > 0 ? port : 8787,
    host: env.HOST || "127.0.0.1",
    publicBaseUrl,
    linear: {
      clientId: env.LINEAR_CLIENT_ID || "",
      clientSecret: env.LINEAR_CLIENT_SECRET || "",
      webhookSecret: env.LINEAR_WEBHOOK_SECRET || "",
      oauthScopes: String(
        env.LINEAR_OAUTH_SCOPES || "read,write,app:assignable,app:mentionable"
      )
        .split(/[,\s]+/)
        .map((s) => s.trim())
        .filter(Boolean),
      authMode: env.LINEAR_AUTH_MODE === "client_credentials" ? "client_credentials" : "oauth",
      webhookMaxAgeMs:
        Number.isFinite(webhookMaxAgeMs) && webhookMaxAgeMs >= 0 ? webhookMaxAgeMs : 300000,
    },
    router: {
      mode: env.ROUTER_MODE === "rules" ? "rules" : "hybrid",
      model: env.ROUTER_MODEL || "gemini-3.8-flash-low",
      timeoutMs:
        Number.isFinite(routerTimeoutMs) && routerTimeoutMs > 0 ? routerTimeoutMs : 90000,
    },
    launcher: {
      remoteMode: env.AGY_REMOTE_MODE || projectsConfig.defaultMode || "accept-edits",
      maxConcurrentLaunches: Number.isFinite(maxConcurrentLaunches) ? maxConcurrentLaunches : 2,
      detachMode: env.LAUNCH_DETACH_MODE !== "false",
      agyBin: env.AGY_BIN || "agy",
      pythonBin: env.PYTHON_BIN || "python3",
    },
    paths: {
      envFile,
      projectsFile,
      projectsExampleFile,
      tokensFile: path.join(rootDir, "data", "tokens.json"),
      sessionsFile: path.join(rootDir, "data", "sessions.json"),
      logsDir: path.join(rootDir, "logs"),
      launchScript: path.join(rootDir, "scripts", "launch_remote_agent.py"),
      watchScript: path.join(rootDir, "scripts", "watch_remote_agent.py"),
      cancelScript: path.join(rootDir, "scripts", "cancel_remote_agent.py"),
    },
    watcher: {
      enabled: env.WATCHER_ENABLED !== "false",
      statusThrottleMs: Number(env.WATCHER_STATUS_THROTTLE_MS || 12_000),
      actionThrottleMs: Number(env.WATCHER_ACTION_THROTTLE_MS || 15_000),
      keepaliveMs: Number(env.WATCHER_KEEPALIVE_MS || 900_000),
      idleGraceMs: Number(env.WATCHER_IDLE_GRACE_MS || 5_000),
      maxConcurrent: Math.max(1, Number(env.WATCHER_MAX_CONCURRENT || 4)),
      maxDurationSec: Math.max(60, Number(env.WATCHER_MAX_DURATION_SEC || 7_200)),
    },
    workflow: {
      enabled: env.WORKFLOW_FETCH_ENABLED !== "false",
      cacheTtlMs:
        env.WORKFLOW_CACHE_TTL_MS !== undefined && env.WORKFLOW_CACHE_TTL_MS !== ""
          ? Math.max(0, Number(env.WORKFLOW_CACHE_TTL_MS) || 0)
          : 300_000,
      timeoutMs:
        env.WORKFLOW_TIMEOUT_MS !== undefined && env.WORKFLOW_TIMEOUT_MS !== ""
          ? Math.max(500, Number(env.WORKFLOW_TIMEOUT_MS) || 8_000)
          : 8_000,
      ghBin: env.GH_BIN || "gh",
    },
    github: {
      webhookSecret: env.GITHUB_WEBHOOK_SECRET || "",
      ciAutoFix: env.GITHUB_CI_AUTO_FIX !== "false",
      reviewAutoResume: env.GITHUB_REVIEW_AUTO_RESUME !== "false",
      maxCiFixRounds:
        env.GITHUB_MAX_CI_FIX_ROUNDS !== undefined && env.GITHUB_MAX_CI_FIX_ROUNDS !== ""
          ? Math.max(0, Number(env.GITHUB_MAX_CI_FIX_ROUNDS) || 0)
          : 3,
      ignoredActors: String(env.GITHUB_IGNORED_ACTORS || "")
        .split(/[,\s]+/)
        .map((s) => s.trim().toLowerCase())
        .filter(Boolean),
    },
    projectsConfig,
  };
}

/**
 * Load the latest `projects.json` from disk on demand so config edits take effect immediately.
 */
export function getProjectsConfig(config) {
  const projectsFile = config?.paths?.projectsFile;
  const projectsExampleFile = config?.paths?.projectsExampleFile || null;
  if (projectsFile && fs.existsSync(projectsFile)) {
    return loadProjectsConfig(projectsFile, projectsExampleFile);
  }
  return (
    config?.projectsConfig || {
      defaultRemoteProject: "",
      defaultMode: "accept-edits",
      projects: [],
    }
  );
}
